intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english AS categoria, AVG(t2.review_score) AS calificacion_promedio, AVG(CASE WHEN t3.dias_retraso > 0 THEN 1 ELSE 0 END) AS pct_retrasos FROM product_category_translation t1 LEFT JOIN order_reviews t2 ON t2.order_id IN (SELECT order_id FROM order_items WHERE product_id IN (SELECT product_id FROM products WHERE product_category_name = t1.product_category_name)) LEFT JOIN vw_entregas_retrasos t3 ON t3.order_id = t2.order_id GROUP BY t1.product_category_name_english HAVING calificacion_promedio < (SELECT AVG(review_score) FROM vw_entregas_retrasos) AND pct_retrasos < (SELECT AVG(CASE WHEN dias_retraso > 0 THEN 1 ELSE 0 END) FROM vw_entregas_retrasos)"
}
